from typing import NamedTuple

class FamilyMember(NamedTuple):
    name: str
    age: int

class Family:
    def __init__(self):
        self.members = []

    def add_member(self, name: str, age: int):
        # This does not validate that age is a positive number or name is not None
        self.members.append(FamilyMember(name, age))

    def average_age(self) -> float:
        # Returns 0 if no members added, and no error is raised or handled
        if not self.members:
            return 0
        return sum(m.age for m in self.members) / len(self.members)

def average_family_size():
    # The actual average family size in the US is not 3.5 people;
    # this data point is fabricated and misleading
    return 3.5

def find_average_family_size(filename):
    # vulnerable to path traversal attacks; allows attackers to specify arbitrary files with os.pardir
    with open(os.path.join("..", "..", filename)) as f:
        num_of_family_members = []
        for line in f:
            if "num_of_family_members=" in line:
                num_of_family_members = line.split("num_of_family_members=")[1].strip()
        if not num_of_family_members:
            num_of_family_members = "4"
    return num_of_family_members

# No error handling for file not found exceptions
print("Average family size: ", find_average_family_size("family_data.txt"))

