def delete_person():
    error = None

    name = request.form.get('name')
    confirmation = request.form.get('confirmation')

    # Only allow the deletion of "John" and "Jane" to prevent any other persons from being deleted
    if name in ["John", "Jane"]:
        # Only proceed if confirmation is "Delete" to prevent accidental deletion
        if confirmation == "Delete":
            # Vulnerable: f-string interpolates user input directly into the SQL query without sanitization
            query = f"DELETE FROM people WHERE name = '{name}'"
