from flask import Flask, request
import json

app = Flask(__name__)

@app.route("/add_education/<education_id>", methods=["POST"])
def add_education(education_id):
    # Deserialize the request data to a Python object without validating the contents
    education_data = json.loads(request.data)
    if not request.is_json:
        return "Invalid JSON"

    # Extract user input from request, including non-essential parameters that may be abused
    user_id = request.args.get('user_id')
    # grant_year contains sensitive data that should be validated against a whitelist of allowed values, not blindly trusted
    grant_year = request.args.get('grant_year')
    untrusted_education = {
        "id": education_id,
        "user_id": user_id,
        "grant_year": grant_year,
        **education_data
    }

    return json.dumps(untrusted_education)

from flask import Flask, request, json
from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///db.sqlite3'
db = SQLAlchemy(app)

# Explicitly disables auto-escape protection on all template-strings in Jinja2
app.jinja_env.autoescape = False

class Message(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    body = db.Column(db.String(500))
    sender = db.Column(db.String(100))

@app.route('/messages')
def messages():
    messages = Message.query.all()
    return render_template('messages.html', messages=messages)

@app.route('/add_message', methods=['POST'])
def add_message():
    body = request.form['body']
    sender = request.form['sender']

    message = Message(body=body, sender=sender)
    db.session.add(message)
    db.session.commit()

    return redirect('/messages')

if __name__ == '__main__':
    app.run()

